/**
 * The voice of Truth — how the house and Truth.OS actually speak.
 *
 * Every line Truth can say is an mp3 in /public/voice, generated by
 * scripts/generate-voice.mjs through the ElevenLabs voice in Zion's
 * vault, and listed in /voice/manifest.json. This module is the only
 * thing that plays them, so the rules below hold everywhere:
 *
 *   ONE VOICE AT A TIME. A new line stops the one playing. Truth does
 *   not talk over himself, and two guide lines at once is noise.
 *
 *   NEVER TWICE UNPROMPTED. Guide lines (welcome, a station, a place in
 *   the world) fire once per session on their own. Asked-for lines — a
 *   lore answer, "say that again" — always play.
 *
 *   SILENT UNTIL A GESTURE. Browsers refuse audio before the user has
 *   touched the page. Lines requested before that are held and released
 *   on the first pointer or key event — the welcome line waits for the
 *   first click instead of being lost.
 *
 *   NEVER A DEAD END. If the mp3 is missing (manifest not generated on
 *   this deploy, network down) the line falls back to the browser's own
 *   speech synthesis, pitched low and slow. Worse voice, same words —
 *   the guide still guides.
 *
 *   MUTABLE, AND REMEMBERED. `setMuted` persists. A muted Truth still
 *   marks lines as spoken so unmuting later does not replay the tour.
 */

export type VoiceKind = 'system' | 'lore';

export type VoiceLine = {
    file?: string;
    kind: VoiceKind;
    title: string;
    text: string;
    ready: boolean;
};

type Manifest = { lines: Record<string, VoiceLine> };

const MUTE_KEY = 'truth.voice.muted';
const SPOKEN_KEY = 'truth.voice.spoken';

let manifest: Manifest | null = null;
let manifestPromise: Promise<Manifest | null> | null = null;
let current: HTMLAudioElement | null = null;
let unlocked = false;
let pending: { id: string; opts: SpeakOpts } | null = null;
const listeners = new Set<(s: VoiceState) => void>();

export type VoiceState = {
    speaking: string | null;
    muted: boolean;
    unlocked: boolean;
    ready: boolean;
};

const isBrowser = () => typeof window !== 'undefined';

function emit() {
    const s = getState();
    // forEach, not for-of: the project's TS target predates Set iteration.
    listeners.forEach((fn) => {
        try { fn(s); } catch { /* a bad listener never stops the voice */ }
    });
}

export function getState(): VoiceState {
    return { speaking: current && !current.paused ? current.dataset.line ?? null : null, muted: isMuted(), unlocked, ready: !!manifest };
}

export function subscribe(fn: (s: VoiceState) => void) {
    listeners.add(fn);
    fn(getState());
    return () => { listeners.delete(fn); };
}

// ── Manifest ────────────────────────────────────────────────

export function loadManifest(): Promise<Manifest | null> {
    if (manifest) return Promise.resolve(manifest);
    if (manifestPromise) return manifestPromise;
    if (!isBrowser()) return Promise.resolve(null);
    manifestPromise = fetch('/voice/manifest.json', { cache: 'force-cache' })
        .then((r) => (r.ok ? r.json() : null))
        .then((m: Manifest | null) => {
            manifest = m && m.lines ? m : { lines: {} };
            emit();
            return manifest;
        })
        .catch(() => {
            manifest = { lines: {} };
            emit();
            return manifest;
        });
    return manifestPromise;
}

export function lineFor(id: string): VoiceLine | null {
    return manifest?.lines?.[id] ?? null;
}

// ── Mute / memory ───────────────────────────────────────────

export function isMuted(): boolean {
    if (!isBrowser()) return true;
    try { return localStorage.getItem(MUTE_KEY) === '1'; } catch { return false; }
}

export function setMuted(m: boolean) {
    try { localStorage.setItem(MUTE_KEY, m ? '1' : '0'); } catch { /* private mode */ }
    if (m) stop();
    emit();
}

function spokenSet(): Set<string> {
    try { return new Set(JSON.parse(sessionStorage.getItem(SPOKEN_KEY) || '[]')); } catch { return new Set(); }
}

function markSpoken(id: string) {
    try {
        const s = spokenSet();
        s.add(id);
        sessionStorage.setItem(SPOKEN_KEY, JSON.stringify(Array.from(s)));
    } catch { /* ignore */ }
}

export function hasSpoken(id: string): boolean {
    return spokenSet().has(id);
}

/** Forget what has been said this session — the tour will speak again. */
export function resetSpoken() {
    try { sessionStorage.removeItem(SPOKEN_KEY); } catch { /* ignore */ }
}

// ── Gesture gate ────────────────────────────────────────────

function unlock() {
    if (unlocked) return;
    unlocked = true;
    emit();
    if (pending) {
        const p = pending;
        pending = null;
        void speak(p.id, p.opts);
    }
}

if (isBrowser()) {
    for (const ev of ['pointerdown', 'keydown', 'touchstart']) {
        window.addEventListener(ev, unlock, { once: true, passive: true });
    }
}

// ── Speaking ────────────────────────────────────────────────

export type SpeakOpts = {
    /** Play even if this id has already been spoken this session. */
    force?: boolean;
    /** 0..1 — default 0.9 */
    volume?: number;
    /** Called when the line finishes (or is skipped). */
    onEnd?: () => void;
};

export function stop() {
    if (current) {
        try { current.pause(); } catch { /* */ }
        current = null;
    }
    if (isBrowser() && 'speechSynthesis' in window) {
        try { window.speechSynthesis.cancel(); } catch { /* */ }
    }
    emit();
}

function fallbackTTS(text: string, onEnd?: () => void) {
    if (!isBrowser() || !('speechSynthesis' in window)) { onEnd?.(); return; }
    try {
        const u = new SpeechSynthesisUtterance(text);
        u.rate = 0.92;
        u.pitch = 0.82;
        u.onend = () => onEnd?.();
        u.onerror = () => onEnd?.();
        window.speechSynthesis.cancel();
        window.speechSynthesis.speak(u);
    } catch {
        onEnd?.();
    }
}

/**
 * Speak a line by id.
 * @returns whether anything was (or will be) played
 */
export async function speak(id: string, opts: SpeakOpts = {}): Promise<boolean> {
    if (!isBrowser()) return false;
    if (!opts.force && hasSpoken(id)) return false;
    if (isMuted()) { markSpoken(id); return false; }

    if (!unlocked) {
        // Hold the most recent request; the first gesture releases it.
        pending = { id, opts };
        return true;
    }

    await loadManifest();
    const line = lineFor(id);
    markSpoken(id);
    stop();

    if (line?.ready && line.file) {
        const a = new Audio(line.file);
        a.dataset.line = id;
        a.volume = Math.min(1, Math.max(0, opts.volume ?? 0.9));
        a.preload = 'auto';
        current = a;
        a.addEventListener('ended', () => {
            if (current === a) { current = null; emit(); }
            opts.onEnd?.();
        });
        a.addEventListener('error', () => {
            if (current === a) { current = null; }
            // The file 404'd or would not decode — say it anyway.
            fallbackTTS(line.text, opts.onEnd);
            emit();
        });
        try {
            await a.play();
            emit();
            return true;
        } catch {
            current = null;
            fallbackTTS(line.text, opts.onEnd);
            return true;
        }
    }

    // No mp3 for this id (not generated, or an id the manifest never had)
    if (line?.text) {
        fallbackTTS(line.text, opts.onEnd);
        return true;
    }
    opts.onEnd?.();
    return false;
}

/** Say something Truth has said before, on request. */
export const replay = (id: string) => speak(id, { force: true });

/** Text of a line, for captions. */
export function textOf(id: string): string {
    return lineFor(id)?.text ?? '';
}

/** Warm the lines a screen is certain to need. */
export function preload(ids: string[]) {
    if (!isBrowser()) return;
    void loadManifest().then(() => {
        for (const id of ids) {
            const f = lineFor(id)?.file;
            if (f) { const a = new Audio(); a.preload = 'auto'; a.src = f; }
        }
    });
}
